function audit(c,action,detail){const l={at:when(),who:db.role,target:c?c.number:'Sistem',action,detail};db.log.unshift(l);db.log=db.log.slice(0,400);if(c){c.history.unshift({at:l.at,who:l.who,action,detail});c.history=c.history.slice(0,100)}}
function toast(msg,err=false){let wrap=document.getElementById('toast-wrap');if(!wrap)return;let d=document.createElement('div');d.className='toast'+(err?' error':'');d.textContent=msg;wrap.appendChild(d);setTimeout(()=>d.remove(),4000)}
const pill=(txt,kind='gray')=>`<span class="pill ${kind}">${esc(txt)}</span>`;
const kindFor=s=>({VERIFIED:'green',CONFIRMED:'green',APPROVED:'green',VALIDATED:'green',BILLED:'green',PAID:'green',CLOSED:'green',HOLD:'red',MISSING:'red',OVERDUE:'red',REJECTED:'red',ESTIMATED:'amber',PENDING:'amber',REQUESTED:'amber',NOT_BILLED:'amber',NOT_STARTED:'gray',NONE:'gray',NOT_APPLICABLE:'blue',OPEN:'red'}[s]||'blue');
