function riskDays(s){const d=dateDiff(s);return d===null?pill('Perlu sumber','gray'):d<0?pill('Lewat '+Math.abs(d)+' hari','red'):d===0?pill('Hari ini','red'):d<=db.settings.demoThreshold?pill('H-'+d,'amber'):pill('H-'+d,'green')}
function stageTag(c){return pill(`${c.stage}. ${STAGES[c.stage-1].title}`,['','blue','purple','amber','blue','green'][c.stage])}
