function alerts(){let a=[];for(let c of db.containers){if(c.closed)continue;const add=(key,level,title,detail,sop)=>a.push({key:c.id+'_'+key,id:c.id,level,title,detail,sop,container:c.number,stage:c.stage});if(c.doStatus==='HOLD')add('DO','KRITIS','DO / identitas belum valid','SOP-01 · Verifikasi fisik & DO tertahan','SOP-01');if(c.stage===2&&c.eventStatus!=='VERIFIED')add('EVENT','SEDANG','Status kejadian belum diverifikasi','SOP-02/03 · Tally → Admin/CS','SOP-02/03');if(c.stage===3&&c.reuseStatus==='PENDING')add('REUSE','SEDANG','Persetujuan reuse belum selesai','SOP-04 · Perlu konfirmasi pihak berwenang','SOP-04');if(c.stage===3&&c.sekupangStatus!=='CONFIRMED')add('SEK','SEDANG','Tiba Sekupang belum dibuktikan','SOP-04 · Gate log/bukti arrival wajib','SOP-04');if(c.stage===4&&c.type==='MT'&&c.slotStatus!=='CONFIRMED')add('MT','KRITIS','MT belum mendapat slot terkonfirmasi','SOP-06 · Prioritas setara LD, eskalasi','SOP-06');if(c.stage===4&&c.roStatus!=='CONFIRMED')add('RO',c.roStatus==='MISSING'?'KRITIS':'SEDANG','RO belum terkonfirmasi','SOP-06 · Nomor, penerbit, dan bukti RO','SOP-06');if(c.amendmentRef&&!c.amendmentSynced)add('AMD','KRITIS','Amendment belum tercermin di master','SOP-07 · Sinkronisasi dan audit trail','SOP-07');if(c.stage===5&&c.costStatus==='VALIDATED'&&c.billingStatus!=='BILLED')add('BILL','SEDANG','Biaya valid belum ditagih','SOP-07 · Perlu dokumen penagihan','SOP-07');if(c.stage===5&&c.costStatus==='ESTIMATED')add('COST','SEDANG','Biaya masih estimasi','SOP-07 · Verifikasi bukti biaya','SOP-07');const free=dateDiff(c.freeTime),cut=dateDiff(c.cutoff);if(c.stage<5&&free!==null&&free<=db.settings.demoThreshold)add('FREE',free<0?'KRITIS':'SEDANG',free<0?'Free time terlewati':'Free time mendekati tenggat',`SOP-05 · ${fmtDate(c.freeTime)} · sumber ${c.freeTimeSource||'perlu konfirmasi'}`,'SOP-05');if(c.stage===4&&cut!==null&&cut<=db.settings.demoThreshold)add('CUT',cut<0?'KRITIS':'SEDANG',cut<0?'Cut-off terlewati':'Cut-off mendekati tenggat',`SOP-05 · ${fmtDate(c.cutoff)}`,'SOP-05')}
for(let al of db.manualAlerts.filter(z=>!z.closed)){let c=get(al.id);if(c)a.push({key:'MAN-'+al.id+'-'+al.key,id:al.id,level:al.level,title:al.title,detail:al.detail,sop:'SOP-05',container:c.number,stage:c.stage,manual:true,sourceKey:al.key})}
return a.sort((a,b)=>(a.level==='KRITIS'?0:1)-(b.level==='KRITIS'?0:1));}
function gate(c){if(c.stage===1){let missing=[];if(c.doStatus!=='VERIFIED')missing.push('DO belum diverifikasi');if(!c.physicalMatch)missing.push('Nomor fisik belum cocok');if(!c.freeTimeSource)missing.push('Sumber free time belum tercatat');return {ok:!missing.length,missing,next:'Pemakaian',sop:'SOP-01/03'}}
if(c.stage===2){let missing=[];if(c.eventStatus!=='VERIFIED')missing.push('Event lapangan belum tervalidasi');if(c.type==='MT'&&!c.emptyConfirmed)missing.push('Status MT belum dikonfirmasi');return {ok:!missing.length,missing,next:'Reuse / penarikan',sop:'SOP-02/03'}}
if(c.stage===3){let missing=[];if(!['APPROVED','NOT_APPLICABLE'].includes(c.reuseStatus))missing.push('Izin reuse atau pengecualian belum valid');if(c.sekupangStatus!=='CONFIRMED'||!c.sekupangEvidence)missing.push('Bukti tiba Sekupang belum lengkap');return {ok:!missing.length,missing,next:'Voyage & RO',sop:'SOP-04'}}
if(c.stage===4){let missing=[];if(c.slotStatus!=='CONFIRMED'||!c.slotRef)missing.push('Slot belum dikonfirmasi dengan referensi');if(c.roStatus!=='CONFIRMED'||!c.roNum||!c.roEvidence)missing.push('RO belum lengkap & terkonfirmasi');if(!c.voyageActual||!c.actualEvidence)missing.push('Bukti realisasi voyage belum ada');return {ok:!missing.length,missing,next:'Konfirmasi & biaya',sop:'SOP-06/05'}}
const missing=[];if(!c.opClosed)missing.push('Kewajiban operasional belum ditutup');if(!c.finClosed)missing.push('Penutupan finansial belum lengkap');if(c.amendmentRef&&!c.amendmentSynced)missing.push('Amendment belum sinkron master');return {ok:!missing.length,missing,next:'Closed',sop:'SOP-07'}}
