const metric=(label,num,cap,ic='container',color='blue')=>`<article class="metric"><div class="metric-icon ${color}">${icon(ic)}</div><div class="metric-label">${label}</div><div class="metric-value">${num}</div><div class="metric-caption">${cap}</div></article>`;
const panel=(title,body,sub='',right='')=>`<section class="panel"><div class="panel-head"><div><h3 class="panel-title">${title}</h3>${sub?`<div class="panel-sub">${sub}</div>`:''}</div>${right}</div>${body}</section>`;
function searchBar(){return `<div class="table-toolbar"><div class="filters"><label class="search-field">${icon('search')}<input type="search" data-search placeholder="Cari kontainer, DO, pelanggan..." value="${esc(ui.q)}" autocomplete="off"></label><select class="field-select" data-filter="type"><option value="ALL" ${ui.type==='ALL'?'selected':''}>Semua tipe MT/LD</option><option value="MT" ${ui.type==='MT'?'selected':''}>MT · Kosong</option><option value="LD" ${ui.type==='LD'?'selected':''}>LD · Bermuatan</option></select><select class="field-select" data-filter="stage"><option value="ALL">Semua tahapan</option>${STAGES.map((s,i)=>`<option value="${i+1}" ${String(ui.stage)===String(i+1)?'selected':''}>${i+1}. ${s.title}</option>`).join('')}</select></div><div class="filters">${act('export-csv',icon('download')+' Ekspor CSV')}</div></div>`}
function rowOps(c){return `<button type="button" class="mini-action" data-action="detail" data-id="${c.id}">${icon('eye')} Detail</button>`}
function listing(items,mode='all',limit=60){if(!items.length)return `<div class="empty"><div class="big">⌕</div>Tidak ada data yang cocok dengan pencarian / filter.</div>`;
const head=mode==='all'?['Kontainer / Siklus','MT / LD','Pelanggan','Tahap','Lokasi','Free time','Status','Aksi']:mode==='master'?['Kontainer','DO / Job','Pemilik','Cocok fisik','Verifikasi','Free time','Aksi']:mode==='movement'?['Kontainer','Lokasi','Event terakhir','Validasi','Status MT','Tahap','Aksi']:mode==='reuse'?['Kontainer','Reuse / Job baru','Persetujuan','Sekupang','Free time','Tahap','Aksi']:mode==='voyage'?['Kontainer','Tipe','Voyage / Slot','RO','Cut-off','Realisasi','Aksi']:['Kontainer','Kewajiban ops','Biaya','Penagihan','Amendment','Penutupan','Aksi'];
const rows=items.slice(0,limit).map(c=>{let cells=mode==='all'?[`<div class="cell-primary">${esc(c.number)}</div><div class="cell-secondary">${esc(c.cycle)}</div>`,`<span class="type-box ${c.type.toLowerCase()}">${c.type}</span>`,esc(c.customer),stageTag(c),esc(c.location),riskDays(c.freeTime),c.closed?pill('CLOSED','green'):c.doStatus==='HOLD'?pill('HOLD','red'):pill('AKTIF','blue'),rowOps(c)]:mode==='master'?[`<div class="cell-primary">${esc(c.number)}</div><div class="cell-secondary">${esc(c.cycle)}</div>`,`<b>${esc(c.do)}</b><div class="cell-secondary">${esc(c.job)}</div>`,esc(c.owner),c.physicalMatch?pill('Cocok','green'):pill('Belum cocok','red'),pill(statusLabel(c.doStatus),kindFor(c.doStatus)),riskDays(c.freeTime),rowOps(c)]:mode==='movement'?[`<div class="cell-primary">${esc(c.number)}</div>`,esc(c.location),esc(c.latestEvent||'Belum ada'),pill(statusLabel(c.eventStatus),kindFor(c.eventStatus)),c.emptyConfirmed?pill('MT tercatat','green'):pill('Perlu konfirmasi','amber'),stageTag(c),rowOps(c)]:mode==='reuse'?[`<div class="cell-primary">${esc(c.number)}</div>`,`<b>${esc(c.reuseRef||'—')}</b><div class="cell-secondary">${esc(c.reuseJob||'Belum ditetapkan')}</div>`,pill(statusLabel(c.reuseStatus),kindFor(c.reuseStatus)),pill(statusLabel(c.sekupangStatus),kindFor(c.sekupangStatus)),riskDays(c.freeTime),stageTag(c),rowOps(c)]:mode==='voyage'?[`<div class="cell-primary">${esc(c.number)}</div>`,`<span class="type-box ${c.type.toLowerCase()}">${c.type}</span>`,`<b>${esc(c.voyage||'Belum ditetapkan')}</b><div class="cell-secondary">${esc(statusLabel(c.slotStatus))}</div>`,pill(statusLabel(c.roStatus),kindFor(c.roStatus)),riskDays(c.cutoff),c.voyageActual?pill('Ada bukti','green'):pill('Belum ada','amber'),rowOps(c)]:[`<div class="cell-primary">${esc(c.number)}</div>`,c.opClosed?pill('Selesai','green'):pill('Terbuka','amber'),`<b>${money(c.amount)}</b><div class="cell-secondary">${statusLabel(c.costStatus)}</div>`,pill(statusLabel(c.billingStatus),kindFor(c.billingStatus)),c.amendmentRef?(c.amendmentSynced?pill('Sinkron','green'):pill('Belum sinkron','red')):pill('Tidak ada','gray'),c.closed?pill('Closed','green'):pill('Open','amber'),rowOps(c)];return `<tr>${cells.map(a=>`<td>${a}</td>`).join('')}</tr>`}).join('');return `<div class="table-scroll"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div><div class="small-note" style="margin-top:11px">Menampilkan ${Math.min(limit,items.length)} dari ${items.length} catatan (data demo).</div>`}
function dashboard(){const n=nums(),a=alerts(),crit=a.filter(x=>x.level==='KRITIS'),m=STAGES.map((x,i)=>db.containers.filter(c=>c.stage===i+1&&!c.closed).length),top=filtered().filter(c=>!c.closed).sort((a,b)=>(dateDiff(a.freeTime)||0)-(dateDiff(b.freeTime)||0));return `${baseHeader('Operational Control Tower','Visibilitas satu data per kontainer per siklus. Monitoring 5 tahapan, 7 SOP, early warning dan keputusan manajemen.',act('new',icon('plus')+' Tambah Kontainer','primary')+act('reset',icon('refresh')+' Reset Demo'))}
<div class="intro-banner"><div><div class="eyebrow" style="color:#83c8ff">BATAM — SINGAPORE • CONTAINER MANAGEMENT</div><h2>One Container. One Cycle. One Source of Truth.</h2><p>Kebijakan, rekapan harian, prioritas MT setara LD, dan eskalasi kepada Manajer Operasional / Head CS TOL.</p></div><div class="banner-tag">DATA SIMULASI · LOCAL DEMO</div></div>
<div class="metric-grid">${metric('Siklus aktif',n.active,'Belum ditutup seluruhnya','container','blue')}${metric('Exception / HOLD',n.hold,'Pemeriksaan DO / data','alert','red')}${metric('MT belum ter-slot',n.unplanned,'Tahap Voyage & RO','ship','amber')}${metric('Alert aktif',a.length,crit.length+' berstatus kritis','bell-ring','red')}${metric('Siklus closed',n.closed,'Operasional + finansial','shield-check','mint')}</div>
<div class="grid-2">${panel('Lifecycle per tahap',`<div class="summary-progress">${STAGES.map((x,i)=>`<button class="stage-progress" data-action="stage-filter" data-stage="${i+1}"><div class="num">${m[i]}</div><div class="name">${i+1}. ${x.title}</div><div class="sop">${x.sop}</div></button>`).join('')}</div><div class="note-line">SOP-05 berjalan lintas kelima tahap · SOP-03 memvalidasi data dan status sebelum dipakai untuk keputusan.</div>`,'Jumlah siklus aktif berdasarkan tahapan proses',`<button class="link-btn" data-view="sops">Lihat Big Map</button>`)}${panel('Perhatian operasional',a.slice(0,4).map(x=>`<div class="risk-item"><span class="risk-dot ${x.level==='KRITIS'?'':'amber'}"></span><div style="flex:1"><b>${esc(x.title)}</b><p>${esc(x.container)} · ${esc(x.detail)}</p></div><span class="when">${x.sop}</span></div>`).join('')||'<div class="empty">Tidak ada exception yang aktif.</div>','Exception dihitung dari data demo',`<button class="link-btn" data-view="alerts">Lihat semua</button>`)}</div>
<div class="grid-2" style="margin-top:16px">${panel('Status kontrol utama',`<div class="chart-row"><span class="chart-row-label">Master DO</span><div class="bar-wrap"><div class="bar" style="width:${Math.round(db.containers.filter(c=>c.doStatus==='VERIFIED').length/n.total*100)}%"></div></div><span class="bar-value">${db.containers.filter(c=>c.doStatus==='VERIFIED').length}</span></div><div class="chart-row"><span class="chart-row-label">Event valid</span><div class="bar-wrap"><div class="bar" style="width:${Math.round(db.containers.filter(c=>c.eventStatus==='VERIFIED').length/n.total*100)}%"></div></div><span class="bar-value">${db.containers.filter(c=>c.eventStatus==='VERIFIED').length}</span></div><div class="chart-row"><span class="chart-row-label">Reuse approved</span><div class="bar-wrap"><div class="bar" style="width:${Math.round(db.containers.filter(c=>c.reuseStatus==='APPROVED').length/n.total*100)}%"></div></div><span class="bar-value">${db.containers.filter(c=>c.reuseStatus==='APPROVED').length}</span></div><div class="chart-row"><span class="chart-row-label">RO confirmed</span><div class="bar-wrap"><div class="bar" style="width:${Math.round(db.containers.filter(c=>c.roStatus==='CONFIRMED').length/n.total*100)}%"></div></div><span class="bar-value">${db.containers.filter(c=>c.roStatus==='CONFIRMED').length}</span></div><p class="small-note">Jumlah catatan dengan kontrol terpenuhi, bukan KPI resmi perusahaan.</p>`,'Kondisi verifikasi pada master demo')}${panel('Ringkasan Manajemen',`<div class="line-item"><span>Jumlah kontainer MT aktif</span><b>${db.containers.filter(c=>c.type==='MT'&&!c.closed).length}</b></div><div class="line-item"><span>RO hilang / belum final tahap 4</span><b>${db.containers.filter(c=>c.stage===4&&c.roStatus!=='CONFIRMED').length}</b></div><div class="line-item"><span>Amendment belum sinkron</span><b>${db.containers.filter(c=>c.amendmentRef&&!c.amendmentSynced).length}</b></div><div class="line-item"><span>Biaya tervalidasi belum ditagih</span><b>${money(db.containers.filter(c=>c.costStatus==='VALIDATED'&&c.billingStatus!=='BILLED').reduce((s,c)=>s+c.amount,0))}</b></div><div class="line-item"><span>Total estimasi/tercatat (demo)</span><b>${money(db.containers.reduce((s,c)=>s+c.amount,0))}</b></div>`,'Ringkasan bukan data produksi')}</div>
${panel('Kontainer membutuhkan perhatian',listing(top.slice(0,7)),'Klik Detail untuk melihat gate SOP dan melakukan uji alur',`<button class="link-btn" data-view="containers">Semua kontainer</button>`).replace('<section class="panel">','<section class="panel table-panel">')}`}
function containerPage(){let items=filtered();return `${baseHeader('Registrasi Kontainer & Siklus','Satu master resmi per nomor kontainer + ID siklus, lengkap dengan histori, status dan evidence.',act('new',icon('plus')+' Kontainer baru','primary')+act('export-json',icon('download')+' Backup Demo'))}<div class="info-strip">Sumber data master di aplikasi ini adalah <b>localStorage browser</b> (mockup). Pada implementasi nyata harus diganti database terpusat dengan hak akses, lampiran, validasi, dan audit log server.</div>${panel(`Daftar siklus (${items.length})`,searchBar()+listing(items),'SOP-01 / SOP-03 · Data induk sebagai sumber bersama')}`}
function masterPage(){let items=filtered();let hold=db.containers.filter(c=>c.doStatus==='HOLD').length;return `${baseHeader('Master Data & Verifikasi DO','SOP-01 + SOP-03 · F1/F2/X1: validasi nomor fisik, DO, job, pemilik aset, dan sumber ketentuan.',act('new',icon('plus')+' Buat data kontainer','primary'))}<div class="metric-grid">${metric('DO verified',db.containers.filter(c=>c.doStatus==='VERIFIED').length,'Status terverifikasi','file-check')}${metric('Hold / mismatch',hold,'Butuh klarifikasi fisik/DO','alert','red')}${metric('Perlu pemeriksaan',db.containers.filter(c=>c.doStatus==='PENDING').length,'Data yang belum diverifikasi','clock','amber')}${metric('Data induk',db.containers.length,'Jumlah siklus dalam master','container','mint')}</div><div class="info-strip">Aturan gate: kontainer <b>tidak dapat pindah dari Tahap 1</b> sebelum verifikasi DO cocok, bukti diperiksa, dan sumber free time tercatat. Data yang berbeda diberi status HOLD, bukan dianggap valid.</div>${panel(`Register DO & master (${items.length})`,searchBar()+listing(items,'master'))}`}
function movementPage(){let items=filtered();return `${baseHeader('Pencatatan Pergerakan & Verifikasi','SOP-02 + SOP-03 · F3–F5/X2: bukti event, input Tally, serah terima, verifikasi status MT.',act('event',icon('plus')+' Input event baru','primary'))}<div class="info-strip">Pencatatan event belum otomatis membuat status MT valid. Admin/CS harus memverifikasi bukti dan status melalui SOP-03. Form ini menyimpan waktu event dan waktu input secara terpisah.</div>${panel('Register movement',searchBar()+listing(items,'movement'),'Klik Detail untuk event dan verifikasi')}`}
function reusePage(){let items=filtered().filter(c=>c.stage>=3);return `${baseHeader('Reuse, Penarikan & Sekupang','SOP-04 · F6/X3: persetujuan reuse, relasi siklus lama–baru, status kedatangan Sekupang.',act('reuse',icon('plus')+' Ajukan reuse','primary'))}<div class="info-strip">Reuse tidak otomatis memperpanjang free time atau menghapus kewajiban siklus sebelumnya. Untuk tahap 3 → 4, aplikasi demo memerlukan <b>izin / pengecualian resmi</b> dan <b>bukti tiba Sekupang</b>.</div>${panel(`Monitoring reuse (${items.length})`,searchBar()+listing(items,'reuse'))}`}
function voyagePage(){let items=filtered().filter(c=>c.stage>=4);const open=items.filter(c=>c.stage===4);return `${baseHeader('Voyage Planning, Kapasitas & RO','SOP-06 + SOP-05 · F7–F8/X4: MT memiliki prioritas setara LD, RO tercatat, rollover terlacak.',act('voyage',icon('plus')+' Konfirmasi slot / RO','primary'))}<div class="grid-2" style="margin-bottom:17px">${panel('Antrian pengambilan keputusan',`<div class="info-strip" style="margin-bottom:12px"><b>MT setara LD:</b> kandidat dirangking berdasarkan deadline operasional demo, bukan jenis MT/LD. Tidak ada alokasi otomatis, karena aturan kapasitas dan kewenangan resmi masih perlu disahkan.</div>${open.slice().sort((a,b)=>(dateDiff(a.cutoff)||0)-(dateDiff(b.cutoff)||0)).map((c,i)=>`<div class="line-item"><span><b>${esc(c.number)}</b> <span class="type-box ${c.type.toLowerCase()}">${c.type}</span> · ${fmtDate(c.cutoff)} · ${esc(c.slotStatus)}</span><button data-action="detail" data-id="${c.id}" class="mini-action">Kelola</button></div>`).join('')||'<div class="empty">Belum ada voyage terbuka.</div>'}`,'Prioritas demo berdasarkan cut-off')}${panel('Persyaratan realisasi',`<div class="focus-card"><div class="bullet">01</div><div><h4>Slot resmi terkonfirmasi</h4><p>Referensi konfirmasi + pihak yang berwenang</p></div></div><div class="focus-card"><div class="bullet">02</div><div><h4>RO terdokumentasi</h4><p>Nomor/referensi, status, bukti, penerbit</p></div></div><div class="focus-card"><div class="bullet">03</div><div><h4>Realisasi voyage terbukti</h4><p>Bukti milestone aktual, bukan rencana saja</p></div></div><div class="focus-card"><div class="bullet">04</div><div><h4>Rollover berotorisasi</h4><p>Simpan alasan, voyage lama dan baru, dampak biaya</p></div></div>`,'Pemeriksaan gate tahap 4') }</div>${panel(`Daftar voyage (${items.length})`,searchBar()+listing(items,'voyage'))}`}
function alertPage(){let a=alerts().filter(x=>ui.severity==='ALL'||x.level===ui.severity);return `${baseHeader('Early Warning & Eskalasi','SOP-05 lintas tahap 1–5. Pre-alert, ACK, keputusan, bukti penutupan dan tanggung jawab PIC.',act('alert',icon('plus')+' Tambah alert manual','primary'))}<div class="info-strip warn-strip"><b>Aturan DEMO:</b> indikator free time/cut-off memakai H-${db.settings.demoThreshold} untuk kebutuhan uji coba, <b>bukan SLA atau ketentuan resmi</b>. Tanggal asli dan aturan dari carrier/TOL harus dikonfigurasi sebelum operasional.</div><div class="metric-grid">${metric('Total alert',a.length,'Hasil perhitungan demo','bell-ring','red')}${metric('Kritis',a.filter(x=>x.level==='KRITIS').length,'Exception mendesak','alert','red')}${metric('Perlu perhatian',a.filter(x=>x.level==='SEDANG').length,'Watchlist aktif','clock','amber')}${metric('Kontainer terdampak',new Set(a.map(x=>x.id)).size,'Unique container','container','blue')}</div>${panel('Daftar exception & pre-alert',`<div class="filters" style="margin-bottom:14px"><button class="filter-btn ${ui.severity==='ALL'?'active':''}" data-action="severity" data-severity="ALL">Semua</button><button class="filter-btn ${ui.severity==='KRITIS'?'active':''}" data-action="severity" data-severity="KRITIS">Kritis</button><button class="filter-btn ${ui.severity==='SEDANG'?'active':''}" data-action="severity" data-severity="SEDANG">Perlu perhatian</button></div><div class="table-scroll"><table><thead><tr><th>Prioritas</th><th>Kontainer</th><th>Isu / bukti</th><th>SOP</th><th>Tahap</th><th>Aksi</th></tr></thead><tbody>${a.map(x=>`<tr><td>${pill(x.level,x.level==='KRITIS'?'red':'amber')}</td><td><div class="cell-primary">${esc(x.container)}</div></td><td><b>${esc(x.title)}</b><div class="cell-secondary">${esc(x.detail)}</div></td><td>${esc(x.sop)}</td><td>${x.stage}</td><td><button class="mini-action" data-action="alert-detail" data-key="${esc(x.key)}">Tindak lanjut</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Tidak ada alert.</td></tr>'}</tbody></table></div>`,'Kirim alert = belum closed. Tutup setelah bukti dan verifikasi.')}`}
function financePage(){let items=filtered().filter(c=>c.stage===5), pending=items.filter(c=>c.billingStatus!=='BILLED');return `${baseHeader('Amendment, Biaya & Penutupan','SOP-07 · F9–F10/X5–X7: audit perubahan, rekonsiliasi invoice, penagihan dan closure.',act('amendment',icon('plus')+' Registrasi amendment','primary'))}<div class="metric-grid">${metric('Biaya tercatat',money(items.reduce((s,c)=>s+c.amount,0)),'Estimasi dan validasi (IDR)','wallet')}${metric('Belum ditagih',pending.length,'Termasuk status estimasi','clock','amber')}${metric('Amendment belum sinkron',items.filter(c=>c.amendmentRef&&!c.amendmentSynced).length,'Wajib masuk master','alert','red')}${metric('Closed',items.filter(c=>c.closed).length,'Operasional & finansial','shield-check','mint')}</div><div class="info-strip">Penutupan operasional <b>berbeda</b> dengan penutupan finansial. Status penagihan BILLED bukan bukti pembayaran. Pada demo, penutupan finansial mensyaratkan bukti biaya tervalidasi dan nomor tagihan, atau ketentuan nihil biaya yang disetujui.</div>${panel(`Rekonsiliasi & closing (${items.length})`,searchBar()+listing(items,'finance'))}`}
function auditView(){return `${baseHeader('Laporan Manajemen & Audit','Rekap siklus harian, exception, kesiapan data dan jejak perubahan SOP.',act('export-csv',icon('download')+' Ekspor CSV','primary')+act('export-json',icon('download')+' JSON demo')+act('print',icon('printer')+' Cetak'))}<div class="grid-2">${panel('KPI yang dapat diuji',`<div class="line-item"><span>DO verified / total siklus</span><b>${db.containers.filter(c=>c.doStatus==='VERIFIED').length} / ${db.containers.length}</b></div><div class="line-item"><span>Event status verified / total</span><b>${db.containers.filter(c=>c.eventStatus==='VERIFIED').length} / ${db.containers.length}</b></div><div class="line-item"><span>RO confirmed / siklus tahap 4–5</span><b>${db.containers.filter(c=>c.stage>=4&&c.roStatus==='CONFIRMED').length} / ${db.containers.filter(c=>c.stage>=4).length}</b></div><div class="line-item"><span>Amendment belum sinkron</span><b>${db.containers.filter(c=>c.amendmentRef&&!c.amendmentSynced).length}</b></div><div class="line-item"><span>Closed / total</span><b>${nums().closed} / ${nums().total}</b></div>`,'KPI indikatif; target resmi belum ditetapkan')}${panel('Kesiapan penerapan produksi',`<div class="focus-card"><div class="bullet">1</div><div><h4>Konfirmasi pemilik proses</h4><p>GTOL, TOL SG, CS, Tally, Planner, Accounting, Manajer</p></div></div><div class="focus-card"><div class="bullet">2</div><div><h4>Aturan RO dan prioritas</h4><p>Kebijakan MT/LD, kapasitas, rollover dan otorisasi</p></div></div><div class="focus-card"><div class="bullet">3</div><div><h4>SLA dan data waktu resmi</h4><p>Cut-off, free time, reminder T-minus dan pembuktian</p></div></div><div class="focus-card"><div class="bullet">4</div><div><h4>Keamanan & sistem</h4><p>Database, autentikasi, notifikasi, log server, backup</p></div></div>`,'Hal yang belum dapat diwakili mockup')}</div><div class="panel table-panel" style="margin-top:17px"><div class="panel-head"><div><h3 class="panel-title">Audit trail perubahan & keputusan</h3><div class="panel-sub">Simulasi aktivitas dari browser ini</div></div></div><div class="table-scroll"><table><thead><tr><th>Waktu</th><th>Pengguna / peran</th><th>Objek</th><th>Aksi</th><th>Rincian</th></tr></thead><tbody>${db.log.slice(0,70).map(x=>`<tr><td>${timeLabel(x.at)}</td><td>${esc(x.who)}</td><td>${esc(x.target)}</td><td>${esc(x.action)}</td><td>${esc(x.detail)}</td></tr>`).join('')}</tbody></table></div></div>`}
function sopPage(){return `${baseHeader('Peta Proses & Keterkaitan SOP','Big Map menjadi sumber pemetaan tahap, owner, output utama, kode temuan, dan seluruh modul sistem.',act('export-json',icon('download')+' Simpan data demo'))}<div class="intro-banner"><div><div class="eyebrow" style="color:#acd9ff">PROSES MANAJEMEN</div><h2>Kebijakan siklus kontainer · MT setara LD · KPI & Target</h2><p>Rekap harian dan eskalasi: Manajer Operasional, Head CS TOL.</p></div><div class="banner-tag">7 SOP • 5 TAHAP</div></div><div class="steps">${STAGES.map((s,i)=>`<div class="step-card"><div class="step-n">TAHAP ${i+1}</div><strong>${s.title}</strong><p>${s.out}</p><small>${s.sop}</small></div>`).join('')}</div><div class="grid-2">${panel('Pemilik proses & titik kegagalan',STAGES.map((s,i)=>`<div class="line-item"><span style="max-width:62%"><b>${i+1}. ${s.title}</b><br><span class="process-owner">${s.owner}</span></span><span>${pill(s.problems,'amber')}</span></div>`).join(''),'F dan X mengikuti label dari Big Map, tanpa menafsirkan X secara lebih rinci')}${panel('Proses pendukung',`<div class="focus-card"><div class="bullet">01</div><div><h4>Inventory & master data resmi</h4><p>Satu data per kontainer per siklus (SOP-01, 02, 03)</p></div></div><div class="focus-card"><div class="bullet">02</div><div><h4>Pre-alert, cut-off & eskalasi</h4><p>Berlaku sepanjang tahap 1–5 (SOP-05)</p></div></div><div class="focus-card"><div class="bullet">03</div><div><h4>Pihak eksternal</h4><p>TOL Singapore (pemilik kontainer), carrier, terminal</p></div></div>`,'Cross-function control')}</div><h3 style="margin:26px 0 13px;font-size:16px">Kontrol sesuai 7 SOP</h3><div class="sop-grid">${SOP.map(s=>`<div class="sop-card"><div class="sop-number">SOP-${s[0]}</div><h4>${s[1]}</h4><p>${s[2]}</p><div class="sop-meta">${s[3]} · ${s[4]}</div></div>`).join('')}</div><h3 style="margin:25px 0 12px;font-size:16px">Coba skenario UAT secara langsung</h3><div class="sop-grid">${[["C001","F1–F2 · DO mismatch","Verifikasi DO → HOLD → koreksi"],["C003","F3–F5 · Status MT","Catat event → verifikasi MT"],["C006","F6 · Reuse","Ajukan reuse → izin → Sekupang"],["C009","F7–F8 · Voyage & RO","Slot MT → konfirmasi RO → voyage"],["C013","F9–F10 · Biaya","Amendment → sinkron → tagihan"]].map(x=>`<div class="sop-card"><div class="sop-number">${x[1]}</div><h4>${x[2]}</h4><button class="btn small primary" data-action="detail" data-id="${x[0]}">${icon('eye')} Mulai trial</button></div>`).join('')}</div><div class="info-strip" style="margin-top:18px">Kode masalah X1–X7 direproduksi pada tingkat pengelompokan Big Map. Akar masalah rinci dan penanggung jawab per kode perlu dikonfirmasi terhadap diagram F/X sumber asli sebelum konfigurasi sistem produksi.</div>`}
function render(){const n=nums();document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar ${ui.menu?'open':''}"><div class="brand"><div class="brand-logo"><div class="brand-symbol">L</div><div><div class="brand-name">Lean<span>Core</span></div><div class="brand-sub">OPERATIONS INTELLIGENCE</div></div></div></div><nav class="nav-scroll">${VIEWS.map((x,i)=>{let section=i===0||VIEWS[i-1][3]!==x[3];return `${section?`<div class="nav-label">${x[3]}</div>`:''}<button class="nav-item ${ui.view===x[0]?'active':''}" data-view="${x[0]}">${icon(x[2])}<span>${x[1]}</span>${x[0]==='alerts'?`<small class="nav-count">${alerts().length}</small>`:''}</button>`}).join('')}</nav><div class="sidebar-footer"><span class="tag">● SIMULASI · BUKAN LIVE</span><small>GTOL • Batam–Singapore<br>Mockup v1.0 · SOP alignment</small></div></aside><main class="main"><header class="topbar"><div class="topbar-left"><button class="menu-toggle" data-action="menu">${icon('menu',22)}</button><div class="crumb">GTOL <span style="padding:0 8px">/</span> <strong>${VIEWS.find(x=>x[0]===ui.view)?.[1]}</strong></div></div><div class="topbar-right"><div class="system-date">${icon('calendar')} ${new Date().toLocaleDateString('id-ID',{day:'2-digit',month:'long',year:'numeric'})}</div><select title="Pilih peran untuk simulasi hak akses" class="role-picker" id="role-change">${ROLES.map(x=>`<option ${db.role===x?'selected':''}>${x}</option>`).join('')}</select><div class="avatar">${db.role.split(' ').map(x=>x[0]).join('').replace(/\W/g,'').slice(0,2).toUpperCase()}</div></div></header><div class="workspace" id="view-content">${({dashboard,containers:containerPage,master:masterPage,movement:movementPage,reuse:reusePage,voyage:voyagePage,alerts:alertPage,finance:financePage,reports:auditView,sops:sopPage})[ui.view]()}<div class="foot-note">© LeanCore Consulting · UI prototype for GTOL. Data dan simulasi transaksi bersifat fiktif. Bukan pengganti SOP yang telah disahkan atau sistem operasional resmi.</div></div></main></div><div id="modal-holder"></div><div id="toast-wrap" class="toast-wrap"></div>`;if(ui.modal)drawModal();}
const input=(name,label,value='',type='text',more='')=>`<div class="form-group"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${more}></div>`;
const sel=(name,label,opts,current)=>`<div class="form-group"><label>${label}</label><select name="${name}">${opts.map(o=>{let v=Array.isArray(o)?o[0]:o,txt=Array.isArray(o)?o[1]:o;return `<option value="${esc(v)}" ${v===current?'selected':''}>${esc(txt)}</option>`}).join('')}</select></div>`;
const area=(name,label,value='')=>`<div class="form-group full"><label>${label}</label><textarea name="${name}" rows="3">${esc(value)}</textarea></div>`;
const readonly=(label,value)=>`<div class="detail-box"><div class="key">${label}</div><div class="val">${value}</div></div>`;
const fwrap=(name,content,submit='Simpan & catat perubahan',notice='')=>`${notice?`<div class="modal-notice">${notice}</div>`:''}<form data-form="${name}"><div class="form-grid">${content}</div><div class="form-footer">${btn('modal-close','Batal') }<button type="submit" class="btn primary">${icon('check')}${submit}</button></div></form>`;
const actionList=(c)=>{if(c.closed)return '<div class="info-strip">Siklus CLOSED. Transaksi baru diblokir; histori tetap dapat diperiksa.</div>';let v=[];const push=(key,label)=>v.push(`<button class="btn small ${key==='advance'?'primary':'subtle'}" data-action="${key}" data-id="${c.id}">${label}</button>`);
if(c.stage===1)push('do',icon('file-check')+' Verifikasi DO');if(c.stage===2){push('event',icon('truck')+' Catat event');push('verify',icon('shield-check')+' Validasi event')}
if(c.stage===3){push('reuse',icon('repeat')+' Ajukan reuse');push('approve',icon('check')+' Persetujuan reuse');push('arrival',icon('flag')+' Tiba Sekupang')}
if(c.stage===4){push('voyage',icon('ship')+' Update slot & RO');push('actual',icon('check')+' Realisasi voyage');push('rollover',icon('repeat')+' Rollover')}
if(c.stage===5){push('amendment',icon('file-check')+' Amendment');if(c.amendmentRef&&!c.amendmentSynced)push('sync',icon('refresh')+' Sinkron amendment');push('cost',icon('wallet')+' Validasi biaya');push('billing',icon('file-check')+' Catat penagihan');push('opclose',icon('check')+' Tutup operasional');push('finclose',icon('check')+' Tutup finansial')}
push('advance',icon('arrow-right')+ (c.stage===5?' Final closing':' Tahap berikutnya'));return `<div style="display:flex;gap:7px;flex-wrap:wrap;margin:10px 0">${v.join('')}</div>`};
function renderDetails(c){let g=gate(c),tabs=['overview','timeline','controls'],labels={'overview':'Ringkasan','timeline':'Jejak Kejadian','controls':'Gate & SOP'};let body=ui.detailTab==='overview'?`<div class="detail-grid">${readonly('Nomor kontainer',esc(c.number))}${readonly('Siklus / referensi',esc(c.cycle))}${readonly('Jenis & status',`<span class="type-box ${c.type.toLowerCase()}">${c.type}</span> ${c.closed?pill('Closed','green'):stageTag(c)}`)}${readonly('DO & booking',esc(c.do)+' / '+esc(c.booking))}${readonly('Customer / job',esc(c.customer)+' / '+esc(c.job))}${readonly('Pemilik aset',esc(c.owner))}${readonly('Lokasi',esc(c.location))}${readonly('Sisa free time',riskDays(c.freeTime))}${readonly('Validasi DO',pill(statusLabel(c.doStatus),kindFor(c.doStatus)))}${readonly('Event & status MT',pill(statusLabel(c.eventStatus),kindFor(c.eventStatus)))}${readonly('Persetujuan reuse',pill(statusLabel(c.reuseStatus),kindFor(c.reuseStatus)))}${readonly('Tiba Sekupang',pill(statusLabel(c.sekupangStatus),kindFor(c.sekupangStatus)))}${readonly('Slot & voyage',esc(c.voyage||'—')+' / '+esc(statusLabel(c.slotStatus)))}${readonly('RO (dokumen resmi)',esc(c.roNum||'—')+' / '+esc(statusLabel(c.roStatus)))}${readonly('Biaya tercatat',money(c.amount))}${readonly('Penagihan',pill(statusLabel(c.billingStatus),kindFor(c.billingStatus)))}</div>`:ui.detailTab==='timeline'?`<div class="timeline">${c.history.map(h=>`<div class="timeline-entry"><b>${esc(h.action)}</b><p>${esc(h.detail)}</p><small>${timeLabel(h.at)} · ${esc(h.who)}</small></div>`).join('')}</div>`:`<div class="detail-grid">${readonly('SOP-01 · DO',pill(statusLabel(c.doStatus),kindFor(c.doStatus)))}${readonly('SOP-02/03 · event',pill(statusLabel(c.eventStatus),kindFor(c.eventStatus)))}${readonly('SOP-04 · reuse',pill(statusLabel(c.reuseStatus),kindFor(c.reuseStatus)))}${readonly('SOP-04 · Sekupang',pill(statusLabel(c.sekupangStatus),kindFor(c.sekupangStatus)))}${readonly('SOP-05 · free time',riskDays(c.freeTime))}${readonly('SOP-06 · slot/RO',pill(statusLabel(c.slotStatus),kindFor(c.slotStatus))+' '+pill(statusLabel(c.roStatus),kindFor(c.roStatus)))}${readonly('SOP-07 · operasional',c.opClosed?pill('Closed','green'):pill('Open','amber'))}${readonly('SOP-07 · finansial',c.finClosed?pill('Closed','green'):pill('Open','amber'))}</div><p class="small-note" style="margin-top:14px">Tahap 1–5 mengikuti Big Map. Pembuktian langkah tidak mengubah kebijakan/SLA tanpa persetujuan organisasi.</p>`;
return `<div class="modal-notice">${esc(STAGES[c.stage-1].title)} · ${esc(STAGES[c.stage-1].owner)}. Kode masalah: ${esc(STAGES[c.stage-1].problems)}.</div><div class="tab-row">${tabs.map(t=>`<button type="button" class="tab ${t===ui.detailTab?'active':''}" data-action="detail-tab" data-tab="${t}" data-id="${c.id}">${labels[t]}</button>`).join('')}</div>${body}<div class="data-divider"></div><div style="display:flex;align-items:center;justify-content:space-between;gap:10px"><b style="font-size:12px">Gate menuju ${g.next}</b>${pill(g.ok?'SIAP':'BELUM SIAP',g.ok?'green':'red')}</div><div style="margin:9px 0 13px;font-size:10.5px;color:#687c91">${g.ok?`Bukti minimum ${g.sop} tersedia. Dapat diproses oleh peran yang berwenang.`:g.missing.map(x=>'• '+esc(x)).join('<br>')}</div><b style="font-size:10px;color:#8998a7">AKSI YANG DAPAT DIUJI · GANTI PERAN DI HEADER JIKA DIPERLUKAN</b>${actionList(c)}`}
function selectContainer(action){const req={do:1,event:2,verify:2,reuse:3,approve:3,arrival:3,voyage:4,actual:4,rollover:4,amendment:5,sync:5,cost:5,billing:5,opclose:5,finclose:5};const candidates=db.containers.filter(c=>!c.closed&&(!req[action]||c.stage===req[action]));return candidates.length?`<form data-form="pick" data-next="${action}"><div class="form-grid"><div class="form-group full"><label>Pilih kontainer untuk transaksi ${esc(action)}</label><select name="selected" required>${candidates.map(c=>`<option value="${c.id}">${esc(c.number)} · Tahap ${c.stage} · ${esc(c.customer)}</option>`).join('')}</select></div></div><div class="form-footer">${btn('modal-close','Batal')}<button type="submit" class="btn primary">Lanjutkan ${icon('chevron-right')}</button></div></form>`:'<div class="empty">Belum tersedia kontainer aktif pada tahap yang sesuai. Buka Kontainer & Siklus untuk mengelola gate sebelumnya.</div>'}
function modalDefinition(action,c){switch(action){case 'new':return ['Registrasi Kontainer Baru','SOP-01 · nomor + siklus, DO, sumber ketentuan',fwrap('new',input('number','Nomor kontainer (unik)','')+input('cycle','ID siklus (unik)','')+sel('type','Tipe kontainer',['MT','LD'],'MT')+input('owner','Pemilik aset','TOL Singapura')+input('do','Nomor DO','')+input('job','Job / shipment','')+input('customer','Customer','')+input('location','Lokasi awal','Batam Port')+input('freeTime','Tanggal akhir free time',plus(5),'date')+input('cutoff','Cut-off voyage (jika ada)',plus(7),'date'),'Simpan data awal','Data akan masuk tahap 1 dengan status verifikasi PENDING, belum dapat dipakai sebagai bukti DO cocok.')];
case 'do':return ['Verifikasi DO & data fisik','SOP-01 / SOP-03 · F1, F2, X1',fwrap('do',sel('physicalMatch','Nomor fisik = master?',[['yes','Ya, cocok'],['no','Tidak cocok']],c.physicalMatch?'yes':'no')+sel('docMatch','DO sesuai job & kontainer?',[['yes','Ya, sesuai'],['no','Tidak sesuai']],c.docMatch?'yes':'no')+input('freeTimeSource','Sumber resmi free time',c.freeTimeSource,'text','required')+input('evidence','Bukti pemeriksaan fisik / dokumen','','text','required')+area('notes','Catatan ketidaksesuaian / tindak lanjut',''),'Simpan verifikasi','Jika identitas/DO tidak cocok, status otomatis HOLD; verifikasi perlu bukti dan sumber resmi.')];
case 'event':return ['Catat kejadian lapangan','SOP-02 · Tally, sopir, serah terima',fwrap('event',sel('event','Jenis kejadian',[['PICKUP','Pengambilan'],['DELIVERED','Pengantaran'],['UNLOADED_MT','Selesai bongkar / MT'],['GATE_IN','Gate-in'],['RETURN','Pengembalian / serah terima'],['ARRIVAL_SEKUPANG','Tiba Sekupang'],['OTHER','Pergerakan lain']],'UNLOADED_MT')+input('actualAt','Waktu aktual kejadian',new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16),'datetime-local','required')+input('location','Lokasi kejadian',c.location,'text','required')+input('evidence','Referensi bukti / tanda terima','','text','required')+area('notes','Catatan kejadian / penerima'),'Catat event menunggu verifikasi','SOP-02 hanya merekam fakta. Status akan PENDING hingga verifikasi SOP-03.')];
case 'verify':return ['Verifikasi perubahan status','SOP-03 · pemeriksaan silang atas event terbaru',fwrap('verify',sel('result','Hasil verifikasi',[['VERIFIED','Sesuai bukti · VERIFIED'],['HOLD','Ada selisih · HOLD']],'VERIFIED')+input('evidence','Referensi bukti pembanding','','text','required')+area('reason','Catatan hasil pemeriksaan'),'Simpan keputusan verifikasi','Sesuai SOP-03, gunakan HOLD jika ada konflik atau bukti tidak memadai.')];
case 'reuse':return ['Ajukan reuse / perubahan siklus','SOP-04 · relasi job baru + kewajiban siklus lama',fwrap('reuse',input('reuseJob','Job baru / shipment baru',c.reuseJob,'text','required')+input('plannedDate','Rencana tiba Sekupang',plus(2),'date','required')+input('requestRef','Referensi permintaan / komunikasi','','text','required')+area('reason','Alasan reuse dan kewajiban lama'),'Ajukan kepada pihak berwenang','Persetujuan reuse tidak otomatis mengubah allowance / free time.')];
case 'approve':return ['Persetujuan reuse','SOP-04 · otorisasi TOL Singapura/pemilik aset',fwrap('approve',sel('result','Keputusan',[['APPROVED','Disetujui'],['NOT_APPLICABLE','Tidak berlaku dengan pengecualian resmi'],['REJECTED','Ditolak']],'APPROVED')+input('ref','Nomor/referensi persetujuan','','text','required')+area('reason','Cakupan izin / alasan pengecualian / bukti'),'Simpan keputusan resmi','Demo memodelkan kewenangan TOL SG atau Manajer Operasional. Pada implementasi nyata, matriks harus disahkan.')];
case 'arrival':return ['Konfirmasi kedatangan Sekupang','SOP-04 · milestone yang ditetapkan Big Map',fwrap('arrival',input('date','Tanggal tiba Sekupang',plus(0),'date','required')+input('evidence','Gate log / tally / bukti arrival','','text','required')+input('location','Lokasi','Sekupang','text','required')+area('notes','Catatan penerimaan / pihak pemeriksa'),'Konfirmasi tiba','Bukti fisik yang dapat ditelusuri wajib ada. Rute pengecualian perlu otorisasi resmi (belum dimodelkan penuh).')];
case 'voyage':return ['Update slot, kapasitas & RO','SOP-06 · Konfirmasi tidak sama dengan pengajuan',fwrap('voyage',input('voyage','Referensi voyage',c.voyage,'text','required')+input('voyageDate','Tanggal rencana voyage',c.voyageDate,'date','required')+sel('slotStatus','Status slot',[['PENDING','Diajukan / belum final'],['CONFIRMED','Dikonfirmasi resmi'] ],c.slotStatus==='CONFIRMED'?'CONFIRMED':'PENDING')+input('slotRef','Referensi konfirmasi slot',c.slotRef)+sel('roStatus','Status RO',[['PENDING','Menunggu'],['MISSING','Tidak ditemukan'],['CONFIRMED','Dikonfirmasi resmi']],['PENDING','MISSING','CONFIRMED'].includes(c.roStatus)?c.roStatus:'PENDING')+input('roNum','Nomor / referensi RO',c.roNum)+input('roEvidence','Penerbit / bukti RO',c.roEvidence)+input('confirmation','Pihak konfirmasi kapasitas / slot','Carrier / Planner Kapal'),'Perbarui voyage & RO','Slot dan RO baru berstatus CONFIRMED ketika referensi resmi dan bukti tersedia. Prioritas MT dan LD setara.')];
case 'actual':return ['Realisasi voyage','SOP-06 · status realisasi memakai bukti aktual',fwrap('actual',input('actualDate','Tanggal milestone realisasi',plus(0),'date','required')+input('evidence','Manifest / gate-in / bukti sailing','','text','required')+area('notes','Keterangan actual vs plan'),'Catat milestone aktual','Hanya diperbolehkan ketika slot dan RO sudah terkonfirmasi.')];
case 'rollover':return ['Otorisasi perubahan voyage / rollover','SOP-06 + SOP-05 · simpan histori & biaya potensial',fwrap('rollover',input('newVoyage','Referensi voyage pengganti','','text','required')+input('newDate','Tanggal voyage baru',plus(5),'date','required')+input('approvalRef','Referensi keputusan & pihak berwenang','','text','required')+input('estimatedCost','Estimasi biaya tambahan (IDR)',0,'number','min="0"')+area('reason','Alasan rollover / dampak pelanggan / free time'),'Konfirmasi rollover','Tidak boleh mengganti voyage lama tanpa jejak keputusan dan dampaknya.')];
case 'amendment':return ['Registrasi amendment','SOP-07 · perubahan wajib masuk master resmi',fwrap('amendment',input('ref','Referensi amendment',c.amendmentRef,'text','required')+input('source','Dasar / pengirim amendment','','text','required')+area('change','Apa yang berubah? tanggal, ketentuan, tarif, atau dokumen'),'Simpan amendment belum sinkron','Amendment akan masuk antrean sinkronisasi agar tidak hilang sebelum rekonsiliasi biaya.')];
case 'sync':return ['Sinkron amendment ke master','SOP-07 · audit perubahan sebelum closing',fwrap('sync',input('evidence','Bukti master diperbarui / referensi koreksi','','text','required')+area('reason','Field/nilai yang diperbarui dan pemeriksa'),'Tandai telah sinkron','Penutupan akhir diblokir selama amendment belum sinkron.')];
case 'cost':return ['Rekonsiliasi & validasi biaya','SOP-07 · estimasi ≠ biaya tervalidasi',fwrap('cost',input('amount','Nilai biaya (IDR)',c.amount,'number','required min="0"')+sel('costStatus','Hasil pemeriksaan',[['ESTIMATED','Estimasi · belum diverifikasi'],['VALIDATED','Biaya tervalidasi'],['DISPUTE','Dispute / selisih'] ],c.costStatus==='VALIDATED'?'VALIDATED':'ESTIMATED')+input('proof','Invoice pemasok / dasar tarif / bukti',c.costProof,'text','required')+area('reason','Rincian periode, selisih, approval biaya'),'Simpan hasil rekonsiliasi','Tidak mengesahkan pembayaran. Validasi memerlukan bukti, sesuai kewenangan Accounting.')];
case 'billing':return ['Pencatatan penagihan','SOP-07 · biaya yang telah divalidasi',fwrap('billing',input('invoiceRef','Nomor invoice / tagihan',c.invoiceRef,'text','required')+input('billDate','Tanggal tagihan',plus(0),'date','required')+input('evidence','Bukti penerbitan / pengiriman invoice','','text','required')+area('notes','Catatan piutang / customer'),'Catat sudah ditagih','BILLED hanya berarti tagihan diterbitkan, bukan otomatis diterima / dibayar.')];
case 'opclose':return ['Penutupan kewajiban operasional','SOP-07 · pisahkan operasional vs finansial',fwrap('opclose',input('evidence','Bukti return / serah terima / konfirmasi kewajiban',c.opEvidence,'text','required')+area('notes','Rincian status akhir & kewajiban tersisa'),'Konfirmasi selesai operasional','Operasional selesai harus memiliki bukti yang cocok dengan kontainer dan siklus.')];
case 'finclose':return ['Penutupan finansial','SOP-07 · membutuhkan bukti penyelesaian keuangan',fwrap('finclose',input('evidence','Bukti pembayaran / settlement / credit note','','text','required')+area('notes','Dokumen persetujuan, selisih dan status akhir'),'Konfirmasi selesai finansial','Bukti settlement dibutuhkan; BILLED sendiri belum membuktikan penutupan finansial.')];
case 'alert':return ['Buat pre-alert manual','SOP-05 · tindakan, PIC dan batas respons',fwrap('alert',sel('containerId','Kontainer / siklus',db.containers.filter(z=>!z.closed).map(z=>[z.id,z.number+' · Tahap '+z.stage]),c?.id||db.containers[0].id)+sel('level','Level risiko',['KRITIS','SEDANG'],'SEDANG')+input('title','Judul risiko','','text','required')+input('detail','Tindakan diminta, PIC, batas waktu & bukti','','text','required'),'Buat alert terbuka','Pembuatan alert tidak berarti penyelesaian. Penutupan wajib dengan bukti.')];
default:return ['Tidak dikenali','','<div class="empty">Aksi belum tersedia.</div>']}}
function drawModal(){const holder=document.getElementById('modal-holder');if(!ui.modal){holder.innerHTML='';return}const action=ui.modal,c=ui.id?get(ui.id):null;let title,sub,body,wide=false;if(action==='detail'&&c){wide=true;title=c.number+' · '+c.cycle;sub=c.customer+' • '+c.location;body=renderDetails(c)}else if(action==='pick'){title='Pilih kontainer';sub='Pilih objek dan lanjutkan transaksi SOP';body=selectContainer(ui.nextAction||'event')}else if(action==='alert-detail'){let al=alerts().find(x=>x.key===ui.alertKey);title=al?'Tindak lanjut · '+al.container:'Exception tidak ditemukan';sub=al?al.sop+' · '+al.level:'';body=al?`<div class="modal-notice"><b>${esc(al.title)}</b><p style="margin-bottom:0">${esc(al.detail)}</p></div><div class="form-footer" style="justify-content:flex-start">${btn('detail',icon('eye')+' Lihat kontainer','subtle',`data-id="${al.id}"`)}${al.manual?btn('resolve-alert',icon('check')+' Tutup dengan bukti','primary',`data-key="${esc(al.key)}"`):btn('ack-alert',icon('bell-ring')+' Catat ACK / eskalasi','primary',`data-key="${esc(al.key)}"`)}</div>`:'<div class="empty">Data alert telah berubah.</div>'}else if(action==='resolve-alert'){title='Verifikasi penutupan alert';sub='SOP-05 · hanya manual alert dapat ditutup dengan bukti';body=fwrap('resolve-alert',input('evidence','Bukti tindakan selesai','','text','required')+area('notes','Keputusan / verifikator'),'Tutup alert berdasar bukti')}else{let x=modalDefinition(action,c);[title,sub,body]=x}holder.innerHTML=`<div class="modal-overlay" data-action="overlay-close"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><h3>${esc(title)}</h3><p>${sub}</p></div><button class="icon-btn" data-action="modal-close" aria-label="Tutup">${icon('x')}</button></div><div class="modal-content">${body}</div></div></div>`}
function openModal(action,id=null){if(action==='detail')ui.detailTab='overview';let c=id?get(id):null;const requires=['do','event','verify','reuse','approve','arrival','voyage','actual','rollover','amendment','sync','cost','billing','opclose','finclose','alert'];if(action!=='alert'&&requires.includes(action)&&!c){ui.nextAction=action;ui.modal='pick';ui.id=null;drawModal();return}
const key={do:'master',event:'event',verify:'verify',reuse:'reuseRequest',approve:'reuseApprove',arrival:'arrival',voyage:'voyage',actual:'voyage',rollover:'voyage',amendment:'amendment',sync:'amendment',cost:'finance',billing:'finance',opclose:'opClose',finclose:'finClose',alert:'alert'}[action];if(key&&!ensurePerm(key))return;
if(c&&c.closed&&action!=='detail'){toast('Siklus telah CLOSED. Gunakan kontainer lain atau Reset Demo.',true);return}if(c&&action!=='detail'&&action!=='alert-detail'){const stageReq={do:[1],event:[2],verify:[2],reuse:[3],approve:[3],arrival:[3],voyage:[4],actual:[4],rollover:[4],amendment:[5],sync:[5],cost:[5],billing:[5],opclose:[5],finclose:[5]};if(stageReq[action]&&!stageReq[action].includes(c.stage)){toast(`Aksi ${action} hanya untuk tahap ${stageReq[action].join(', ')}. Kontainer berada di tahap ${c.stage}.`,true);return}}
ui.modal=action;ui.id=id;drawModal()}
function closeModal(){ui.modal='';ui.id=null;document.getElementById('modal-holder').innerHTML=''}
function advance(c){const perm=c.stage===4?'voyage':c.stage===5?'finClose':'master';if(!ensurePerm(perm))return;const g=gate(c);if(!g.ok){toast('Belum bisa lanjut: '+g.missing.join(' · '),true);openModal('detail',c.id);return}if(c.stage===5){c.closed=true;audit(c,'SIKLUS CLOSED','Penutupan operasional, finansial dan amendment terverifikasi.');toast(c.number+' berhasil ditutup.')}else{let old=c.stage;c.stage+=1;audit(c,'PINDAH TAHAP',`${old}. ${STAGES[old-1].title} → ${c.stage}. ${STAGES[c.stage-1].title}; gate ${g.sop} lulus.`);toast(c.number+' pindah ke Tahap '+c.stage)}save();ui.modal='';render()}
function values(form){const o={};new FormData(form).forEach((v,k)=>o[k]=String(v).trim());return o}
function must(x,msg){if(!x){toast(msg,true);throw Error('form validation: '+msg)}}
function handleSubmit(form){const name=form.dataset.form,f=values(form);if(name==='pick'){ui.modal='';openModal(form.dataset.next,f.selected);return}let c=ui.id?get(ui.id):null;if(name!=='new'&&name!=='alert'&&name!=='resolve-alert'&&!c){toast('Kontainer belum dipilih.',true);return}try{switch(name){
case 'new':{must(f.number&&f.cycle&&f.do&&f.job&&f.customer,'Lengkapi nomor kontainer, siklus, DO, job dan customer.');must(!db.containers.some(z=>z.number.replace(/\W/g,'')===f.number.replace(/\W/g,'')&&z.cycle===f.cycle),'Pasangan kontainer/siklus ini sudah terdaftar.');must(!db.containers.some(z=>z.cycle===f.cycle),'ID siklus harus unik.');let n=db.containers.length+1;let z={id:'C'+String(n).padStart(3,'0'),number:f.number.toUpperCase(),cycle:f.cycle,type:f.type,owner:f.owner||'TOL Singapura',location:f.location,customer:f.customer,job:f.job,do:f.do,booking:'',stage:1,freeTime:f.freeTime,cutoff:f.cutoff,freeTimeSource:'',physicalMatch:false,docMatch:false,doStatus:'PENDING',eventStatus:'PENDING',emptyConfirmed:false,latestEvent:'',reuseStatus:'NONE',reuseRef:'',reuseJob:'',sekupangStatus:'PENDING',sekupangEvidence:'',sekupangDate:'',slotStatus:'NOT_STARTED',slotRef:'',voyage:'',voyageDate:'',roStatus:'NOT_STARTED',roNum:'',roEvidence:'',voyageActual:false,actualEvidence:'',amendmentRef:'',amendmentSynced:true,amount:0,costStatus:'NOT_STARTED',costProof:'',billingStatus:'NOT_STARTED',invoiceRef:'',opClosed:false,opEvidence:'',finClosed:false,closed:false,history:[],notes:''};db.containers.push(z);audit(z,'REGISTRASI','Siklus baru, menunggu verifikasi DO.');toast('Kontainer baru ditambahkan.');break}
case 'do':{must(f.evidence&&f.freeTimeSource,'Bukti dan sumber free time wajib diisi.');c.physicalMatch=f.physicalMatch==='yes';c.docMatch=f.docMatch==='yes';c.freeTimeSource=f.freeTimeSource;c.doStatus=c.physicalMatch&&c.docMatch?'VERIFIED':'HOLD';audit(c,'SOP-01 VERIFIKASI',`Hasil ${c.doStatus}; bukti ${f.evidence}; sumber ${f.freeTimeSource}; ${f.notes}`);toast('Hasil DO: '+c.doStatus);break}
case 'event':{must(f.evidence&&f.location&&f.actualAt,'Isi event, lokasi, waktu aktual dan bukti.');c.latestEvent=f.event;c.eventStatus='PENDING';c.emptyConfirmed=false;c.location=f.location;c.eventEvidence=f.evidence;c.actualAt=f.actualAt;audit(c,'SOP-02 EVENT',`${f.event} @ ${f.location}, waktu aktual ${f.actualAt}; bukti ${f.evidence}; ${f.notes}`);toast('Event dicatat; perlu verifikasi SOP-03.');break}
case 'verify':{must(c.latestEvent,'Catat event lapangan dahulu (SOP-02).');must(f.evidence,'Bukti pembanding tidak boleh kosong.');c.eventStatus=f.result;c.emptyConfirmed=f.result==='VERIFIED'&&c.latestEvent==='UNLOADED_MT';audit(c,'SOP-03 VERIFIKASI',`Hasil ${f.result}; ${c.latestEvent}; bukti ${f.evidence}; ${f.reason}`);toast('Status event: '+f.result);break}
case 'reuse':{must(f.reuseJob&&f.requestRef,'Job baru dan bukti permintaan wajib ada.');c.reuseJob=f.reuseJob;c.reuseStatus='PENDING';c.reuseRequest=f.requestRef;c.sekupangPlanned=f.plannedDate;audit(c,'SOP-04 AJUKAN REUSE',`Job baru ${f.reuseJob}; rencana tiba ${f.plannedDate}; referensi ${f.requestRef}; ${f.reason}`);toast('Permintaan reuse dicatat, menunggu persetujuan.');break}
case 'approve':{must(f.ref,'Referensi keputusan wajib ada.');must(c.reuseJob||f.result==='NOT_APPLICABLE','Ajukan reuse dan tetapkan job baru sebelum persetujuan.');must(f.result!=='NOT_APPLICABLE'||f.reason,'Pengecualian harus menyebutkan alasan dan cakupan resmi.');c.reuseStatus=f.result;c.reuseRef=f.ref;audit(c,'SOP-04 KEPUTUSAN REUSE',`${f.result}; ${f.ref}; ${f.reason}`);toast('Keputusan reuse: '+statusLabel(f.result));break}
case 'arrival':{must(f.evidence&&f.date&&f.location,'Lengkapi tanggal, bukti arrival dan lokasi.');c.sekupangStatus='CONFIRMED';c.sekupangEvidence=f.evidence;c.sekupangDate=f.date;c.location=f.location;audit(c,'SOP-04 SEKUPANG',`Tiba ${f.date}, lokasi ${f.location}, bukti ${f.evidence}; ${f.notes}`);toast('Tiba Sekupang terkonfirmasi.');break}
case 'voyage':{must(f.voyage&&f.voyageDate,'Voyage dan tanggal wajib diisi.');if(f.slotStatus==='CONFIRMED')must(f.slotRef&&f.confirmation,'Slot confirmed memerlukan referensi dan pihak konfirmasi.');if(f.roStatus==='CONFIRMED')must(f.roNum&&f.roEvidence,'RO confirmed wajib punya nomor/referensi dan bukti penerbit.');c.voyage=f.voyage;c.voyageDate=f.voyageDate;c.slotStatus=f.slotStatus;c.slotRef=f.slotStatus==='CONFIRMED'?f.slotRef:'';c.roStatus=f.roStatus;c.roNum=f.roStatus==='CONFIRMED'?f.roNum:'';c.roEvidence=f.roStatus==='CONFIRMED'?f.roEvidence:'';c.slotConfirmation=f.confirmation;audit(c,'SOP-06 SLOT / RO',`Voyage ${f.voyage}; slot ${f.slotStatus} (${c.slotRef||'belum final'}); RO ${f.roStatus} ${c.roNum}; pihak ${f.confirmation}`);toast('Slot dan RO diperbarui.');break}
case 'actual':{must(c.slotStatus==='CONFIRMED'&&c.roStatus==='CONFIRMED','Slot dan RO harus sama-sama confirmed.');must(f.actualDate&&f.evidence,'Tanggal aktual dan bukti wajib diisi.');c.voyageActual=true;c.actualEvidence=f.evidence;c.actualDate=f.actualDate;audit(c,'SOP-06 VOYAGE ACTUAL',`Milestone aktual ${f.actualDate}; bukti ${f.evidence}; ${f.notes}`);toast('Realisasi voyage dibuktikan.');break}
case 'rollover':{must(f.newVoyage&&f.newDate&&f.approvalRef&&f.reason,'Rollover memerlukan voyage baru, tanggal, otorisasi dan alasan.');let old=c.voyage;c.voyage=f.newVoyage;c.voyageDate=f.newDate;c.slotStatus='PENDING';c.slotRef='';c.roStatus='PENDING';c.roNum='';c.roEvidence='';c.voyageActual=false;c.actualEvidence='';if(Number(f.estimatedCost)>0){c.amount+=Number(f.estimatedCost);c.costStatus='ESTIMATED'}audit(c,'SOP-06 ROLLOVER',`${old} → ${f.newVoyage}; approval ${f.approvalRef}; biaya estimasi ${money(f.estimatedCost)}; alasan ${f.reason}`);toast('Rollover dicatat. Slot & RO harus dikonfirmasi ulang.');break}
case 'amendment':{must(f.ref&&f.source&&f.change,'Referensi, sumber, dan rincian amendment wajib ada.');c.amendmentRef=f.ref;c.amendmentSynced=false;c.amendmentDetail=f.change;audit(c,'SOP-07 AMENDMENT',`${f.ref} dari ${f.source}; ${f.change}; status BELUM SINKRON`);toast('Amendment masuk antrean sinkronisasi master.');break}
case 'sync':{must(c.amendmentRef&&f.evidence,'Amendment dan bukti sinkronisasi wajib ada.');c.amendmentSynced=true;audit(c,'SOP-07 SINKRON MASTER',`${c.amendmentRef}, bukti ${f.evidence}; ${f.reason}`);toast('Amendment dikonfirmasi sinkron.');break}
case 'cost':{must(f.proof,'Perlu bukti tarif / invoice pemasok.');must(Number(f.amount)>=0,'Nilai biaya tidak valid.');c.amount=Number(f.amount);c.costStatus=f.costStatus;c.costProof=f.proof;if(f.costStatus!=='VALIDATED'){c.finClosed=false;c.closed=false}audit(c,'SOP-07 REKONSILIASI',`Status ${f.costStatus}; jumlah ${money(c.amount)}; bukti ${f.proof}; ${f.reason}`);toast('Rekonsiliasi biaya disimpan.');break}
case 'billing':{must(c.costStatus==='VALIDATED','Validasi biaya oleh Accounting terlebih dahulu.');must(f.invoiceRef&&f.evidence&&f.billDate,'Bukti invoice dan tanggal tidak boleh kosong.');c.invoiceRef=f.invoiceRef;c.billingStatus='BILLED';c.billingEvidence=f.evidence;audit(c,'SOP-07 PENAGIHAN',`Invoice ${f.invoiceRef}, tanggal ${f.billDate}, bukti ${f.evidence}; ${f.notes}`);toast('Penagihan telah tercatat; tidak otomatis lunas.');break}
case 'opclose':{must(f.evidence,'Bukti return atau penyelesaian kewajiban wajib.');c.opClosed=true;c.opEvidence=f.evidence;audit(c,'SOP-07 OPS CLOSED',`Konfirmasi operasional selesai; ${f.evidence}; ${f.notes}`);toast('Kewajiban operasional telah diverifikasi.');break}
case 'finclose':{must(c.costStatus==='VALIDATED','Biaya harus tervalidasi.');must(c.billingStatus==='BILLED','Penagihan harus tercatat, sebelum financial closing.');must(!c.amendmentRef||c.amendmentSynced,'Amendment harus sinkron ke master.');must(f.evidence,'Bukti settlement / credit note wajib.');c.finClosed=true;c.finEvidence=f.evidence;audit(c,'SOP-07 FIN CLOSED',`Bukti settlement ${f.evidence}; ${f.notes}`);toast('Status finansial ditutup berdasarkan bukti.');break}
case 'alert':{c=get(f.containerId);must(c&&f.title&&f.detail,'Pilih kontainer, isi risiko, PIC dan tindakan.');const id='AL'+Date.now();db.manualAlerts.unshift({key:id,id:c.id,level:f.level,title:f.title,detail:f.detail,closed:false});audit(c,'SOP-05 PRE-ALERT',`${f.level} · ${f.title}; ${f.detail}`);toast('Pre-alert dicatat sebagai OPEN.');break}
case 'resolve-alert':{const al=db.manualAlerts.find(z=>'MAN-'+z.id+'-'+z.key===ui.alertKey);must(al,'Alert manual tidak ditemukan.');must(f.evidence,'Bukti penyelesaian wajib ada.');al.closed=true;al.evidence=f.evidence;al.closedAt=when();audit(get(al.id),'SOP-05 ALERT CLOSED',`${al.title}; bukti ${f.evidence}; ${f.notes}`);toast('Alert manual ditutup setelah bukti.');break}
default:throw Error('Unknown form '+name)}save();closeModal();render()}catch(e){if(!String(e.message).startsWith('form validation'))toast('Gagal menyimpan: '+e.message,true);console.warn(e)}}
function exportCSV(){const fields=['number','cycle','type','stage','customer','owner','location','do','doStatus','freeTime','cutoff','eventStatus','reuseStatus','sekupangStatus','slotStatus','voyage','roStatus','roNum','amendmentRef','amendmentSynced','amount','costStatus','billingStatus','opClosed','finClosed','closed'];const cells=s=>`"${String(s??'').replaceAll('"','""')}"`;const rows=[fields.map(cells).join(','),...db.containers.map(c=>fields.map(k=>cells(c[k])).join(','))];download('GTOL_Container_Control_Tower_demo.csv','\uFEFF'+rows.join('\r\n'),'text/csv;charset=utf-8');toast('CSV demo berhasil diekspor.')}
function exportJSON(){download('GTOL_Container_Control_Tower_demo.json',JSON.stringify({warning:'DATA MOCKUP / SIMULASI. Bukan hasil audit atau data riil GTOL.',...db},null,2),'application/json;charset=utf-8');toast('Backup JSON demo dibuat.')}
function download(name,content,type){let url=URL.createObjectURL(new Blob([content],{type}));let a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200)}
function nav(view){if(!VIEWS.some(x=>x[0]===view))return;ui.view=view;ui.q='';ui.type='ALL';ui.stage='ALL';ui.menu=false;ui.modal='';ui.severity='ALL';window.scrollTo({top:0,behavior:'auto'});render()}
document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){nav(view.dataset.view);return}const target=e.target.closest('[data-action]');if(!target)return;const x=target.dataset.action,id=target.dataset.id;switch(x){case 'menu':ui.menu=!ui.menu;render();break;case 'overlay-close':if(e.target===target)closeModal();break;case 'modal-close':closeModal();break;case 'new':case 'detail':case 'do':case 'event':case 'verify':case 'reuse':case 'approve':case 'arrival':case 'voyage':case 'actual':case 'rollover':case 'amendment':case 'sync':case 'cost':case 'billing':case 'opclose':case 'finclose':case 'alert':openModal(x,id);break;case 'detail-tab':ui.detailTab=target.dataset.tab;ui.modal='detail';ui.id=id;drawModal();break;case 'stage-filter':ui.stage=target.dataset.stage;ui.view='containers';ui.q='';ui.modal='';render();break;case 'advance':{let c=get(id);if(c)advance(c);break}case 'export-csv':exportCSV();break;case 'export-json':exportJSON();break;case 'print':window.print();break;case 'reset':if(confirm('Hapus perubahan demo dan kembalikan 15 contoh kontainer awal?')){db=seed();save();ui.view='dashboard';ui.q='';ui.stage='ALL';ui.type='ALL';render();toast('Semua data sampel telah dipulihkan.')};break;case 'severity':ui.severity=target.dataset.severity;render();break;case 'alert-detail':{ui.alertKey=target.dataset.key;ui.modal='alert-detail';ui.id=null;drawModal();break}case 'resolve-alert':{ui.alertKey=target.dataset.key;ui.modal='resolve-alert';drawModal();break}case 'ack-alert':{let al=alerts().find(x=>x.key===target.dataset.key);if(al){if(!ensurePerm('alert'))return;let c=get(al.id);audit(c,'SOP-05 ACK / ESKALASI',`${al.title}; alert tetap OPEN sampai kontrol terpenuhi.`);save();toast('ACK tercatat. Exception tetap terbuka hingga isu selesai.');closeModal();render()}break}}});
document.addEventListener('submit',e=>{if(e.target.matches('form[data-form]')){e.preventDefault();handleSubmit(e.target)}});
document.addEventListener('change',e=>{if(e.target.id==='role-change'){db.role=e.target.value;save();render();toast('Peran demo: '+db.role)}if(e.target.matches('[data-filter]')){ui[e.target.dataset.filter]=e.target.value;let field=document.activeElement;render()}});
document.addEventListener('input',e=>{if(e.target.matches('[data-search]')){ui.q=e.target.value;const pos=e.target.selectionStart;const y=e.target.closest('.panel');if(y){const list=y.querySelector('.table-scroll');if(list){let source=ui.view==='reuse'?filtered().filter(c=>c.stage>=3):ui.view==='voyage'?filtered().filter(c=>c.stage>=4):ui.view==='finance'?filtered().filter(c=>c.stage===5):filtered();let mode=({master:'master',movement:'movement',reuse:'reuse',voyage:'voyage',finance:'finance'})[ui.view]||'all';let parent=list.parentElement;let temp=document.createElement('div');temp.innerHTML=listing(source,mode);list.replaceWith(temp.querySelector('.table-scroll'));const foot=parent.querySelector('.small-note:last-child');if(foot)foot.textContent=`Menampilkan ${source.length} catatan (data demo).`}}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal)closeModal()});
render();
